     1	/**
     2	 * Attachment metadata plus the storage quota guard.
     3	 *
     4	 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit
     5	 */
     6	import { wouldExceedLimit } from "@/config/plan-limits";
     7	import { assertCan } from "@/lib/permissions";
     8	import { assertOrgScope } from "@/lib/tenant";
     9	import * as attachmentRepo from "@/server/repositories/attachment-repository";
    10	import * as issueRepo from "@/server/repositories/issue-repository";
    11	import * as orgRepo from "@/server/repositories/organization-repository";
    12	import * as usageRepo from "@/server/repositories/usage-repository";
    13	import { issueResource, requireFound } from "./_support";
    14	import type {
    15	  CreateAttachmentInput,
    16	  DeleteAttachmentInput,
    17	} from "@/schemas/attachment";
    18	import type { IssueId, OrgId } from "@/types/common";
    19	import type { IssueAttachment } from "@/types/issue";
    20	import type { Actor } from "@/types/member";
    21	
    22	const BYTES_PER_MB = 1024 * 1024;
    23	
    24	export async function listAttachments(
    25	  actor: Actor,
    26	  orgId: OrgId,
    27	  issueId: IssueId,
    28	): Promise<readonly IssueAttachment[]> {
    29	  assertOrgScope(actor, orgId);
    30	
    31	  const issue = requireFound(
    32	    await issueRepo.findIssueById(orgId, issueId),
    33	    "Issue",
    34	    issueId,
    35	  );
    36	  assertCan(actor, "issue:read", issueResource(issue));
    37	
    38	  return attachmentRepo.listAttachments(orgId, issueId);
    39	}
    40	
    41	/**
    42	 * Records an upload after checking the org still has storage left. The quota
    43	 * is in megabytes and the upload is in bytes, so the incoming size is rounded
    44	 * up to whole megabytes before the comparison — half a megabyte still costs
    45	 * one against the plan.
    46	 */
    47	export async function addAttachment(
    48	  actor: Actor,
    49	  input: CreateAttachmentInput,
    50	): Promise<IssueAttachment> {
    51	  assertOrgScope(actor, input.orgId);
    52	
    53	  const issue = requireFound(
    54	    await issueRepo.findIssueById(input.orgId, input.issueId),
    55	    "Issue",
    56	    input.issueId,
    57	  );
    58	  assertCan(actor, "issue:update", issueResource(issue));
    59	
    60	  const org = requireFound(
    61	    await orgRepo.findOrgById(input.orgId),
    62	    "Organization",
    63	    input.orgId,
    64	  );
    65	
    66	  const usage = await usageRepo.getUsage(input.orgId);
    67	  const requestedMb = Math.ceil(input.sizeBytes / BYTES_PER_MB);
    68	
    69	  if (
    70	    wouldExceedLimit(org.plan, "storageMb", usage.storageMbUsed, requestedMb)
    71	  ) {
    72	    throw new Error(
    73	      `Plan ${org.plan} has no room for another ${requestedMb} MB`,
    74	    );
    75	  }
    76	
    77	  const attachment = await attachmentRepo.insertAttachment(
    78	    input,
    79	    actor.userId,
    80	  );
    81	  await usageRepo.incrementUsage(input.orgId, { storageMbUsed: requestedMb });
    82	
    83	  return attachment;
    84	}
    85	
    86	/** Removing an attachment gives the megabytes back to the quota. */
    87	export async function removeAttachment(
    88	  actor: Actor,
    89	  input: DeleteAttachmentInput,
    90	): Promise<void> {
    91	  assertOrgScope(actor, input.orgId);
    92	
    93	  const attachment = requireFound(
    94	    await findAttachment(input.orgId, input.attachmentId),
    95	    "Attachment",
    96	    input.attachmentId,
    97	  );
    98	
    99	  const issue = requireFound(
   100	    await issueRepo.findIssueById(input.orgId, attachment.issueId),
   101	    "Issue",
   102	    attachment.issueId,
   103	  );
   104	  assertCan(actor, "issue:update", issueResource(issue));
   105	
   106	  await attachmentRepo.deleteAttachment(input.orgId, input.attachmentId);
   107	  await usageRepo.incrementUsage(input.orgId, {
   108	    storageMbUsed: -Math.ceil(attachment.sizeBytes / BYTES_PER_MB),
   109	  });
   110	}
   111	
   112	/**
   113	 * The attachment repository only reads by issue, because that is the only way
   114	 * the UI ever reaches one. A delete arrives with just an id, so the org's
   115	 * issues are walked until the row turns up.
   116	 */
   117	async function findAttachment(
   118	  orgId: OrgId,
   119	  attachmentId: string,
   120	): Promise<IssueAttachment | null> {
   121	  const page = await issueRepo.listIssues({
   122	    orgId,
   123	    limit: 100,
   124	    cursor: null,
   125	    includeArchived: true,
   126	  });
   127	
   128	  for (const issue of page.items) {
   129	    const rows = await attachmentRepo.listAttachments(orgId, issue.id);
   130	    const match = rows.find((row) => row.id === attachmentId);
   131	    if (match) return match;
   132	  }
   133	
   134	  return null;
   135	}
---MEMBER---
     1	/**
     2	 * Membership and role changes, including the invariant that an organization always keeps one owner.
     3	 *
     4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
     5	 */
     6	import { emit } from "@/lib/event-bus";
     7	import { assertCan } from "@/lib/permissions";
     8	import { assertOrgScope } from "@/lib/tenant";
     9	import * as memberRepo from "@/server/repositories/member-repository";
    10	import { hasRoleAtLeast } from "@/types/member";
    11	import { actorEnvelope, memberResource, requireFound } from "./_support";
    12	import type {
    13	  ListMembersInput,
    14	  RemoveMemberInput,
    15	  UpdateMemberRoleInput,
    16	} from "@/schemas/member";
    17	import type { MemberId, OrgId, Page, UserId } from "@/types/common";
    18	import type { Actor, Member, MemberWithUser, Role } from "@/types/member";
    19	
    20	/** How many members are scanned when counting the remaining owners. */
    21	const OWNER_SCAN_LIMIT = 100;
    22	
    23	export async function listMembers(
    24	  actor: Actor,
    25	  input: ListMembersInput,
    26	): Promise<Page<MemberWithUser>> {
    27	  assertOrgScope(actor, input.orgId);
    28	  assertCan(actor, "member:read", {
    29	    kind: "organization",
    30	    orgId: input.orgId,
    31	  });
    32	  return memberRepo.listMembers(input);
    33	}
    34	
    35	/**
    36	 * Role changes carry two rules the permission matrix cannot express:
    37	 * nobody may grant a role above their own, and the last owner may not be
    38	 * demoted. Both are checked after `can()` has had its say.
    39	 */
    40	export async function updateMemberRole(
    41	  actor: Actor,
    42	  input: UpdateMemberRoleInput,
    43	): Promise<Member> {
    44	  assertOrgScope(actor, input.orgId);
    45	
    46	  const member = requireFound(
    47	    await memberRepo.findMemberById(input.orgId, input.memberId),
    48	    "Member",
    49	    input.memberId,
    50	  );
    51	  assertCan(actor, "member:update_role", memberResource(member));
    52	
    53	  if (!hasRoleAtLeast(actor.role, input.role)) {
    54	    throw new Error(
    55	      `A ${actor.role} cannot grant the ${input.role} role`,
    56	    );
    57	  }
    58	
    59	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
    60	
    61	  const updated = await memberRepo.updateMemberRole(
    62	    input.orgId,
    63	    input.memberId,
    64	    input.role,
    65	  );
    66	
    67	  await emit("member.role_changed", {
    68	    ...actorEnvelope(actor),
    69	    memberId: updated.id,
    70	    from: member.role,
    71	    to: updated.role,
    72	  });
    73	
    74	  return updated;
    75	}
    76	
    77	/**
    78	 * Removal is a soft delete, and it is subject to the same last-owner rule as a
    79	 * demotion — a removed owner is a demotion to "no role at all".
    80	 */
    81	export async function removeMember(
    82	  actor: Actor,
    83	  input: RemoveMemberInput,
    84	): Promise<Member> {
    85	  assertOrgScope(actor, input.orgId);
    86	
    87	  const member = requireFound(
    88	    await memberRepo.findMemberById(input.orgId, input.memberId),
    89	    "Member",
    90	    input.memberId,
    91	  );
    92	  assertCan(actor, "member:remove", memberResource(member));
    93	
    94	  await assertLastOwnerRetained(input.orgId, input.memberId, "member");
    95	
    96	  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);
    97	
    98	  await emit("member.removed", {
    99	    ...actorEnvelope(actor),
   100	    memberId: removed.id,
   101	    userId: removed.userId,
   102	  });
   103	
   104	  return removed;
   105	}
   106	
   107	/**
   108	 * Turns a (user, org) pair into the `Actor` every service method takes. The
   109	 * only place an `Actor` is minted from stored state — jobs and the session
   110	 * layer both come through here.
   111	 */
   112	export async function resolveActor(
   113	  userId: UserId,
   114	  orgId: OrgId,
   115	): Promise<Actor | null> {
   116	  const member = await memberRepo.findMember(orgId, userId);
   117	  if (!member || member.status !== "active") return null;
   118	
   119	  return { userId, orgId, role: member.role };
   120	}
   121	
   122	/**
   123	 * Throws when applying `nextRole` to `memberId` would leave the organization
   124	 * without an owner. Exported because both the demote and the remove path need
   125	 * it, and the invariant must not be stated twice.
   126	 */
   127	export async function assertLastOwnerRetained(
   128	  orgId: OrgId,
   129	  memberId: MemberId,
   130	  nextRole: Role,
   131	): Promise<void> {
   132	  if (nextRole === "owner") return;
   133	
   134	  const member = await memberRepo.findMemberById(orgId, memberId);
   135	  if (!member || member.role !== "owner") return;
   136	
   137	  const page = await memberRepo.listMembers({
   138	    orgId,
   139	    role: "owner",
   140	    limit: OWNER_SCAN_LIMIT,
   141	    cursor: null,
   142	  });
   143	
   144	  const remaining = page.items.filter((row) => row.id !== memberId);
   145	  if (remaining.length === 0) {
   146	    throw new Error(
   147	      "An organization must keep at least one owner; transfer ownership first",
   148	    );
   149	  }
   150	}

