     1	/**
     2	 * Server-side flag context construction and the org-level override toggle.
     3	 *
     4	 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
     5	 */
     6	import { emit } from "@/lib/event-bus";
     7	import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
     8	import { assertCan } from "@/lib/permissions";
     9	import { getFlagDefinition } from "@/config/feature-flags";
    10	import * as orgRepo from "@/server/repositories/organization-repository";
    11	import { actorEnvelope, orgResource, requireFound } from "./_support";
    12	import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
    13	import type { FeatureFlagSnapshot, FlagContext } from "@/types/feature-flag";
    14	import type { Actor } from "@/types/member";
    15	import type { Organization } from "@/types/organization";
    16	
    17	/**
    18	 * Builds the evaluation context every `isEnabled()` call needs. Both halves
    19	 * are nullable so marketing pages — no session, no org — can still ask about
    20	 * a flag and get the free-plan answer.
    21	 */
    22	export function buildFlagContext(
    23	  actor: Actor | null,
    24	  org: Organization | null,
    25	): FlagContext {
    26	  return {
    27	    orgId: org?.id ?? actor?.orgId ?? null,
    28	    userId: actor?.userId ?? null,
    29	    plan: org?.plan ?? "free",
    30	    role: actor?.role ?? null,
    31	    overrides: org?.settings.enabledFlagOverrides,
    32	  };
    33	}
    34	
    35	/**
    36	 * The serialisable snapshot the dashboard layout hands to the client provider,
    37	 * so `useFeatureFlag()` answers without a round trip and cannot disagree with
    38	 * the server.
    39	 */
    40	export function getSnapshot(
    41	  actor: Actor,
    42	  org: Organization,
    43	): FeatureFlagSnapshot {
    44	  return snapshotFlags(buildFlagContext(actor, org));
    45	}
    46	
    47	/**
    48	 * Adds or removes an org-level override. Only flags declared `overridable`
    49	 * accept one — a flag gated purely on plan cannot be switched on by an admin,
    50	 * which is what keeps the plan boundary meaningful.
    51	 */
    52	export async function toggleFlag(
    53	  actor: Actor,
    54	  input: ToggleFeatureFlagInput,
    55	): Promise<Organization> {
    56	  assertCan(actor, "org:manage_flags", orgResource(input.orgId));
    57	
    58	  const org = requireFound(
    59	    await orgRepo.findOrgById(input.orgId),
    60	    "Organization",
    61	    input.orgId,
    62	  );
    63	
    64	  const definition = getFlagDefinition(input.flag);
    65	  if (!definition.overridable) {
    66	    throw new Error(`Feature "${input.flag}" cannot be overridden per org`);
    67	  }
    68	
    69	  const current = new Set(org.settings.enabledFlagOverrides);
    70	  if (input.enabled) {
    71	    current.add(input.flag);
    72	  } else {
    73	    current.delete(input.flag);
    74	  }
    75	
    76	  const updated = await orgRepo.updateOrg(input.orgId, {
    77	    orgId: input.orgId,
    78	    settings: { enabledFlagOverrides: [...current] },
    79	  });
    80	
    81	  await emit("flag.toggled", {
    82	    ...actorEnvelope(actor),
    83	    flag: input.flag,
    84	    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),
    85	  });
    86	
    87	  return updated;
    88	}
---WEBHOOK---
     1	/**
     2	 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
     3	 *
     4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
     5	 */
     6	import { createHmac } from "node:crypto";
     7	import { wouldExceedLimit } from "@/config/plan-limits";
     8	import { subscribe } from "@/lib/event-bus";
     9	import { isEnabled } from "@/lib/feature-flags";
    10	import { randomToken } from "@/lib/hash";
    11	import { assertCan } from "@/lib/permissions";
    12	import { assertOrgScope } from "@/lib/tenant";
    13	import * as orgRepo from "@/server/repositories/organization-repository";
    14	import * as webhookRepo from "@/server/repositories/webhook-repository";
    15	import { requireFound, webhookResource } from "./_support";
    16	import type {
    17	  CreateWebhookInput,
    18	  DeleteWebhookInput,
    19	  UpdateWebhookInput,
    20	} from "@/schemas/webhook";
    21	import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
    22	import type { OrgId } from "@/types/common";
    23	import type { Unsubscribe } from "@/types/event";
    24	import type { FlagContext } from "@/types/feature-flag";
    25	import type { Actor } from "@/types/member";
    26	
    27	/** Length in bytes of a generated endpoint signing secret. */
    28	const SECRET_BYTES = 32;
    29	
    30	export async function listWebhooks(
    31	  actor: Actor,
    32	  orgId: OrgId,
    33	): Promise<readonly WebhookEndpointRow[]> {
    34	  assertOrgScope(actor, orgId);
    35	  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
    36	  return webhookRepo.listEndpoints(orgId);
    37	}
    38	
    39	/**
    40	 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
    41	 * the org's plan, and the plan's endpoint count must have room. A secret is
    42	 * minted here and never regenerated — rotating it means deleting the endpoint.
    43	 */
    44	export async function createWebhook(
    45	  actor: Actor,
    46	  input: CreateWebhookInput,
    47	): Promise<WebhookEndpointRow> {
    48	  assertOrgScope(actor, input.orgId);
    49	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));
    50	
    51	  const org = requireFound(
    52	    await orgRepo.findOrgById(input.orgId),
    53	    "Organization",
    54	    input.orgId,
    55	  );
    56	
    57	  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
    58	    throw new Error("Outgoing webhooks are not included in this plan");
    59	  }
    60	
    61	  const used = await webhookRepo.countEndpoints(input.orgId);
    62	  if (wouldExceedLimit(org.plan, "webhooks", used)) {
    63	    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
    64	  }
    65	
    66	  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
    67	}
    68	
    69	export async function updateWebhook(
    70	  actor: Actor,
    71	  input: UpdateWebhookInput,
    72	): Promise<WebhookEndpointRow> {
    73	  assertOrgScope(actor, input.orgId);
    74	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
    75	  return webhookRepo.updateEndpoint(input);
    76	}
    77	
    78	export async function deleteWebhook(
    79	  actor: Actor,
    80	  input: DeleteWebhookInput,
    81	): Promise<void> {
    82	  assertOrgScope(actor, input.orgId);
    83	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
    84	  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
    85	}
    86	
    87	/**
    88	 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
    89	 * this from the same secret — it is the only thing proving the delivery came
    90	 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
    91	 */
    92	export function signPayload(secret: string, payload: string): string {
    93	  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
    94	}
    95	
    96	/**
    97	 * Fans domain events out into the delivery table. Each org's endpoints
    98	 * declare which event types they want, so an endpoint only ever receives what
    99	 * it subscribed to; the job drains the rows afterwards.
   100	 */
   101	export function registerWebhookListeners(): Unsubscribe {
   102	  const offs: Unsubscribe[] = [
   103	    subscribe("webhook.delivery_requested", async (payload) => {
   104	      await enqueueForOrg(
   105	        payload.orgId,
   106	        payload.eventType,
   107	        JSON.stringify(payload.payload),
   108	      );
   109	    }),
   110	    subscribe("issue.created", async (payload) => {
   111	      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
   112	    }),
   113	    subscribe("issue.status_changed", async (payload) => {
   114	      await enqueueForOrg(
   115	        payload.orgId,
   116	        "issue.status_changed",
   117	        JSON.stringify(payload),
   118	      );
   119	    }),
   120	    subscribe("comment.created", async (payload) => {
   121	      await enqueueForOrg(
   122	        payload.orgId,
   123	        "comment.created",
   124	        JSON.stringify(payload),
   125	      );
   126	    }),
   127	    subscribe("billing.plan_changed", async (payload) => {
   128	      await enqueueForOrg(
   129	        payload.orgId,
   130	        "billing.plan_changed",
   131	        JSON.stringify(payload),
   132	      );
   133	    }),
   134	  ];
   135	
   136	  return () => {
   137	    for (const off of offs) off();
   138	  };
   139	}
   140	
   141	async function enqueueForOrg(
   142	  orgId: OrgId,
   143	  eventType: string,
   144	  payload: string,
   145	): Promise<void> {
   146	  const endpoints = await webhookRepo.listEndpoints(orgId);
   147	
   148	  for (const endpoint of endpoints) {
   149	    if (!endpoint.enabled) continue;
   150	
   151	    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
   152	    if (!wanted.includes(eventType)) continue;
   153	
   154	    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
   155	  }
   156	}
   157	
   158	function flagContextFor(
   159	  actor: Actor,
   160	  plan: FlagContext["plan"],
   161	  overrides: readonly string[],
   162	): FlagContext {
   163	  return {
   164	    orgId: actor.orgId,
   165	    userId: actor.userId,
   166	    plan,
   167	    role: actor.role,
   168	    overrides,
   169	  };
   170	}
---NOTIF---
     1	/**
     2	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
     3	 *
     4	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
     5	 */
     6	import { subscribe } from "@/lib/event-bus";
     7	import { isEnabled } from "@/lib/feature-flags";
     8	import { assertCan } from "@/lib/permissions";
     9	import { assertOrgScope } from "@/lib/tenant";
