/** Thrown by every write path while its workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is read-only: ${reason}`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * `null` means writable. A missing subscription is writable, as is an active
 * one. A trial locks once its period end is reached, and a cancellation locks
 * once its cancellation date is reached; until then both stay writable.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "past_due":
      return "past_due";
    case "trialing":
      return isReached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null || isReached(subscription.cancelAt, now)
        ? "canceled"
        : null;
    default:
      return null;
  }
}

/** True once `stamp` is at or before `now`. */
function isReached(stamp: string, now: Date): boolean {
  return new Date(stamp).getTime() <= now.getTime();
}

