/**
 * The workspace write lock as the services enforce it: writes are refused while
 * the subscription is out of good standing, while billing and reads keep working.
 */
import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { WorkspaceLockedError } from "@/lib/billing-lock";
import { hashToken, randomToken } from "@/lib/hash";
import { getDb, subscriptions } from "@/server/db";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import type { OrgId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

/** Writes the stored subscription row directly: the lock reads only what is stored. */
function storeSubscription(
  orgId: OrgId,
  values: Partial<typeof subscriptions.$inferInsert>,
): void {
  getDb().update(subscriptions).set(values).where(eq(subscriptions.orgId, orgId)).run();
}

describe("services/workspace lock", () => {
  it("reports no lock while the trial is running", async () => {
    const tenant = await createTenant("lock-active", "growth");

    const summary = await billingService.getBillingSummary(tenant.actors.owner, tenant.org.id);

    expect(summary.lockReason).toBeNull();
  });

  it("refuses an issue write while past due, and the billing summary reports why", async () => {
    const tenant = await createTenant("lock-past-due", "growth");
    storeSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, { title: "Blocked" }),
      ),
    ).rejects.toMatchObject({ code: "plan_limit_exceeded", reason: "past_due", orgId: tenant.org.id });

    const summary = await billingService.getBillingSummary(tenant.actors.owner, tenant.org.id);
    expect(summary.lockReason).toBe("past_due");
  });

  it("refuses sending an invitation while locked", async () => {
    const tenant = await createTenant("lock-invite", "growth");
    storeSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      invitationService.inviteMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        email: "late@lock-invite.test",
        role: "member",
      }),
    ).rejects.toBeInstanceOf(WorkspaceLockedError);
  });

  it("keeps a pending invitation pending and creates no membership while locked", async () => {
    const tenant = await createTenant("lock-accept", "growth");
    const token = randomToken(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "guest@lock-accept.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );
    const guest = await userRepo.insertUser({
      email: "guest@lock-accept.test",
      name: "Guest",
      passwordHash: "seed",
    });
    storeSubscription(tenant.org.id, { status: "past_due" });

    await expect(invitationService.acceptInvitation(guest.id, { token })).rejects.toBeInstanceOf(
      WorkspaceLockedError,
    );

    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.email)).toContain("guest@lock-accept.test");
    expect(await memberRepo.findMember(tenant.org.id, guest.id)).toBeNull();
  });

  it("keeps billing working while locked", async () => {
    const tenant = await createTenant("lock-billing", "growth");
    storeSubscription(tenant.org.id, { status: "past_due" });

    const subscription = await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 6,
    });

    expect(subscription.seats).toBe(6);
  });

  it("makes the workspace writable again once a plan change is made", async () => {
    const tenant = await createTenant("lock-recover", "growth");
    storeSubscription(tenant.org.id, { status: "past_due" });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "After recovery" }),
    );
    expect(issue.title).toBe("After recovery");
  });

  it("locks an ended trial at its period end and not before", async () => {
    const tenant = await createTenant("lock-trial", "growth");
    storeSubscription(tenant.org.id, {
      status: "trialing",
      currentPeriodEnd: "2026-01-15T00:00:00.000Z",
    });

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date("2026-01-14T23:59:59.000Z")),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date("2026-01-15T00:00:00.000Z")),
    ).rejects.toMatchObject({ reason: "trial_ended" });
  });

  it("locks a canceled workspace once its cancellation date passes", async () => {
    const tenant = await createTenant("lock-cancel", "growth");
    storeSubscription(tenant.org.id, {
      status: "canceled",
      cancelAt: "2026-02-01T00:00:00.000Z",
    });

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date("2026-01-31T23:59:59.000Z")),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date("2026-02-01T00:00:00.000Z")),
    ).rejects.toMatchObject({ reason: "canceled" });
  });
});

