/** The pure lock rule: which stored subscriptions leave a workspace read-only, and when. */
import { describe, expect, it } from "vitest";
import { WorkspaceLockedError, lockReasonFor } from "@/lib/billing-lock";
import type { Subscription, SubscriptionStatus } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import { ORG_A } from "../helpers/factories";

const NOW = new Date("2026-06-01T12:00:00.000Z");
const EARLIER = "2026-06-01T11:00:00.000Z" as IsoTimestamp;
const LATER = "2026-06-01T13:00:00.000Z" as IsoTimestamp;

function subscriptionWith(
  status: SubscriptionStatus,
  dates: Partial<Pick<Subscription, "currentPeriodEnd" | "cancelAt">> = {},
): Subscription {
  return {
    id: "01SUB",
    orgId: ORG_A,
    plan: "growth",
    interval: "monthly",
    status,
    seats: 4,
    currentPeriodStart: EARLIER,
    currentPeriodEnd: LATER,
    cancelAt: null,
    createdAt: EARLIER,
    updatedAt: EARLIER,
    ...dates,
  } as Subscription;
}

describe("lib/billing-lock", () => {
  it("leaves a workspace with no subscription writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
  });

  it("leaves an active subscription writable, whatever its dates say", () => {
    const active = subscriptionWith("active", {
      currentPeriodEnd: EARLIER,
      cancelAt: EARLIER,
    });
    expect(lockReasonFor(active, NOW)).toBeNull();
  });

  it("locks a past-due subscription regardless of the time", () => {
    expect(lockReasonFor(subscriptionWith("past_due"), NOW)).toBe("past_due");
  });

  it("keeps a trial writable until its period end is reached", () => {
    expect(lockReasonFor(subscriptionWith("trialing", { currentPeriodEnd: LATER }), NOW)).toBeNull();
  });

  it("locks a trial at the exact moment its period end is reached", () => {
    const end = NOW.toISOString() as IsoTimestamp;
    expect(lockReasonFor(subscriptionWith("trialing", { currentPeriodEnd: end }), NOW)).toBe("trial_ended");
  });

  it("keeps a scheduled cancellation writable until its date", () => {
    expect(lockReasonFor(subscriptionWith("canceled", { cancelAt: LATER }), NOW)).toBeNull();
  });

  it("locks a canceled subscription once its cancellation date is reached", () => {
    expect(lockReasonFor(subscriptionWith("canceled", { cancelAt: EARLIER }), NOW)).toBe("canceled");
  });

  it("locks a canceled subscription that has no cancellation date", () => {
    expect(lockReasonFor(subscriptionWith("canceled", { cancelAt: null }), NOW)).toBe("canceled");
  });

  it("defaults `now` to the current time", () => {
    const ended = subscriptionWith("trialing", { currentPeriodEnd: "2020-01-01T00:00:00.000Z" });
    const future = subscriptionWith("trialing", { currentPeriodEnd: "2999-01-01T00:00:00.000Z" });
    expect(lockReasonFor(ended)).toBe("trial_ended");
    expect(lockReasonFor(future)).toBeNull();
  });

  it("carries the org and reason on the thrown error", () => {
    const error = new WorkspaceLockedError(ORG_A, "past_due");
    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(error.reason).toBe("past_due");
  });
});

